<!-- Página de providers e fontes externas. -->
<script setup lang="ts">import{computed,onMounted,ref}from"vue";import BaseEmptyState from"@/components/base/BaseEmptyState.vue";import BasePageHeader from"@/components/base/BasePageHeader.vue";import ProviderDashboard from"@/components/providers/ProviderDashboard.vue";import ExternalSourceDialog from"@/components/providers/ExternalSourceDialog.vue";import{externalSourceRepository,syncJobRepository}from"@/domain/providers/repository";import type{ExternalSourceRecord,SyncJobRecord}from"@/domain/providers/records";const sources=ref<ExternalSourceRecord[]>([]),jobs=ref<SyncJobRecord[]>([]),loading=ref(true),error=ref(""),search=ref(""),provider=ref(""),dialogOpen=ref(false),editing=ref<ExternalSourceRecord|null>(null);const providers=computed(()=>[...new Set(sources.value.map(x=>x.provider))].sort());const filtered=computed(()=>{const q=search.value.toLocaleLowerCase("pt-PT");return sources.value.filter(x=>(!provider.value||x.provider===provider.value)&&(!q||`${x.expand?.titulo?.titulo||""} ${x.provider} ${x.external_id} ${x.tipo_externo||""}`.toLocaleLowerCase("pt-PT").includes(q)))});async function load(){loading.value=true;try{const[s,j]=await Promise.all([externalSourceRepository.list({page:1,perPage:500,sort:"provider,external_id",expand:"titulo"}),syncJobRepository.list({page:1,perPage:200,sort:"-iniciado_em"})]);sources.value=s.items;jobs.value=j.items}catch(c){error.value=c instanceof Error?c.message:String(c)}finally{loading.value=false}}function create(){editing.value=null;dialogOpen.value=true}function edit(source:ExternalSourceRecord){editing.value=source;dialogOpen.value=true}async function saved(){dialogOpen.value=false;editing.value=null;await load()}onMounted(load);</script><template><BasePageHeader eyebrow="Integrações externas" title="Providers" description="Fontes externas, identificadores e sincronizações por provider."><template #actions><button class="button button-primary" type="button" @click="create">＋ Nova fonte externa</button></template></BasePageHeader><div v-if="error" class="form-alert form-alert-error" role="alert">{{error}}</div><ProviderDashboard :sources="sources" :jobs="jobs"/><section class="panel provider-filters"><label class="form-field"><span>Pesquisar</span><input v-model.trim="search" type="search" placeholder="Título, provider ou identificador"/></label><label class="form-field"><span>Provider</span><select v-model="provider"><option value="">Todos</option><option v-for="item in providers" :key="item">{{item}}</option></select></label></section><p v-if="loading" class="page-loading">A carregar fontes externas…</p><BaseEmptyState v-else-if="!filtered.length" icon="◇" title="Sem fontes externas" description="Ainda não existem fontes para estes filtros."/><div v-else class="table-wrap"><table><thead><tr><th>Título</th><th>Provider</th><th>Identificador</th><th>Tipo</th><th>Principal</th><th>Última sincronização</th><th><span class="sr-only">Ações</span></th></tr></thead><tbody><tr v-for="source in filtered" :key="source.id"><td>{{source.expand?.titulo?.titulo||source.titulo}}</td><td>{{source.provider}}</td><td>{{source.external_id}}</td><td>{{source.tipo_externo||'—'}}</td><td>{{source.principal?'Sim':'Não'}}</td><td>{{source.ultima_sincronizacao?new Date(source.ultima_sincronizacao).toLocaleString('pt-PT'):'Nunca'}}</td><td><div class="library-row-actions"><a v-if="source.external_url" class="button button-secondary" :href="source.external_url" target="_blank" rel="noopener noreferrer">Abrir</a><button class="button button-secondary" type="button" @click="edit(source)">Editar</button></div></td></tr></tbody></table></div><ExternalSourceDialog :open="dialogOpen" :source="editing" :existing="sources" @close="dialogOpen=false" @saved="saved"/></template>
